jQuery(function(t){
    // Existing country/state dropdown logic
    t("select.country_auto").change(function(){
        if(t("select.state_auto").length>0){
            var a=t("select.country_auto").children("option:selected").attr("data-id");
            t("select.state_auto").html('<option value="0">Select State</option>');
            t("select.city_auto").html('<option value="0">Select City</option>');
            jQuery.ajax({
                url:typeof tc_csca_auto_ajax!=='undefined'?tc_csca_auto_ajax.ajax_url:'',
                type:"post",
                dataType:"json",
                data:{action:"tc_csca_get_states",nonce_ajax:typeof tc_csca_auto_ajax!=='undefined'?tc_csca_auto_ajax.nonce:'',cnt:a},
                success:function(a){
                    if(a&&a.length){
                        for(var i=0;i<a.length;i++){
                            var e=a[i].id,c=a[i].name,o="<option data-id='"+e+"' value='"+c+"'>"+c+"</option>";
                            t("select.state_auto").append(o);
                        }
                    }
                }
            });
        }
    });
    t("select.state_auto").change(function(){
        if(t("select.city_auto").length>0){
            var a=t(this).children("option:selected").attr("data-id");
            t("select.city_auto").html('<option value="0">Select City</option>');
            jQuery.ajax({
                url:typeof tc_csca_auto_ajax!=='undefined'?tc_csca_auto_ajax.ajax_url:'',
                type:"post",
                dataType:"json",
                data:{action:"tc_csca_get_cities",nonce_ajax:typeof tc_csca_auto_ajax!=='undefined'?tc_csca_auto_ajax.nonce:'',sid:a},
                success:function(a){
                    if(a&&a.length){
                        for(var i=0;i<a.length;i++){
                            var e=a[i].id,c=a[i].name,o="<option value='"+c+"' data-id='"+e+"'>"+c+"</option>";
                            t("select.city_auto").append(o);
                        }
                    }
                }
            });
        }
    });

    // Advaita Full Mobile Navigation Drawer System
    function initMobileDrawer() {
        if (t(".advaita-mobile-drawer").length > 0) return;

        // Collect navigation items from left and right menus
        var navItemsHtml = '';
        var leftMenu = t("#menu-left-menu");
        var rightMenu = t("#menu-right-menu");

        function processMenu(menu) {
            menu.children("li").each(function(){
                var li = t(this);
                var link = li.children("a").first();
                var text = link.text().trim();
                var href = link.attr("href") || "#";
                var subMenu = li.find("ul.sub-menu");

                if (subMenu.length > 0) {
                    var subItemsHtml = '';
                    subMenu.children("li").each(function(){
                        var subA = t(this).find("a");
                        subItemsHtml += '<li class="advaita-mob-sub-item"><a href="' + (subA.attr("href") || "#") + '">' + subA.text().trim() + '</a></li>';
                    });
                    navItemsHtml += '<li class="advaita-mob-item has-sub">' +
                        '<div class="advaita-mob-link-row">' +
                            '<a href="' + href + '">' + text + '</a>' +
                            '<button type="button" class="advaita-mob-sub-toggle" aria-label="Toggle Submenu"><i class="fa-solid fa-chevron-down"></i></button>' +
                        '</div>' +
                        '<ul class="advaita-mob-sub-menu">' + subItemsHtml + '</ul>' +
                    '</li>';
                } else {
                    navItemsHtml += '<li class="advaita-mob-item"><a href="' + href + '">' + text + '</a></li>';
                }
            });
        }

        if (leftMenu.length) processMenu(leftMenu);
        if (rightMenu.length) processMenu(rightMenu);

        var drawerHtml = 
            '<div class="advaita-drawer-backdrop"></div>' +
            '<div class="advaita-mobile-drawer">' +
                '<div class="advaita-drawer-header">' +
                    '<div class="advaita-drawer-brand">' +
                        '<img src="assets/images/logo.png" alt="Advaita School Logo" class="advaita-drawer-logo">' +
                        '<div class="advaita-drawer-title-wrap">' +
                            '<span class="advaita-drawer-school-name">ADVAITA</span>' +
                            '<span class="advaita-drawer-tagline">School of Excellence</span>' +
                        '</div>' +
                    '</div>' +
                    '<button type="button" class="advaita-drawer-close" aria-label="Close Menu"><i class="fa-solid fa-xmark"></i></button>' +
                '</div>' +
                '<div class="advaita-drawer-actions">' +
                    '<a href="tel:+919689898973" class="advaita-mob-btn btn-call"><i class="fa-solid fa-phone"></i> Call School</a>' +
                    '<a href="https://www.vidyalayaschoolsoftware.com/erp-login?OrgGroupId=W0ksTiurh2iyOL1bEwc2ig==" target="_blank" class="advaita-mob-btn btn-erp"><i class="fa-solid fa-user-lock"></i> ERP Login</a>' +
                    '<a href="admissions.html" class="advaita-mob-btn btn-admissions"><i class="fa-solid fa-graduation-cap"></i> Admissions</a>' +
                '</div>' +
                '<div class="advaita-drawer-body">' +
                    '<ul class="advaita-mob-nav">' + navItemsHtml + '</ul>' +
                '</div>' +
                '<div class="advaita-drawer-footer">' +
                    '<div class="advaita-mob-socials">' +
                        '<a href="https://www.facebook.com/Advaitaschool/" target="_blank"><i class="fa-brands fa-facebook-f"></i></a>' +
                        '<a href="https://wa.me/919689898973" target="_blank"><i class="fa-brands fa-whatsapp"></i></a>' +
                        '<a href="https://twitter.com/Advaitaschool" target="_blank"><i class="fa-brands fa-x-twitter"></i></a>' +
                        '<a href="https://youtube.com" target="_blank"><i class="fa-brands fa-youtube"></i></a>' +
                        '<a href="https://instagram.com" target="_blank"><i class="fa-brands fa-instagram"></i></a>' +
                    '</div>' +
                    '<div class="advaita-drawer-cbse">CBSE Affiliation No. 1130920 · Parbhani</div>' +
                '</div>' +
            '</div>';

        t("body").append(drawerHtml);

        // Event Listeners for Mobile Drawer
        function openDrawer() {
            t(".advaita-mobile-drawer").addClass("active");
            t(".advaita-drawer-backdrop").addClass("active");
            t("body").addClass("mobile-drawer-open");
        }

        function closeDrawer() {
            t(".advaita-mobile-drawer").removeClass("active");
            t(".advaita-drawer-backdrop").removeClass("active");
            t("body").removeClass("mobile-drawer-open");
        }

        t(document).on("click", ".mobile-toggle, .mobile-toggle-wrap a, #header .mobile-toggle", function(e){
            e.preventDefault();
            e.stopPropagation();
            openDrawer();
        });

        t(document).on("click", ".advaita-drawer-close, .advaita-drawer-backdrop", function(e){
            e.preventDefault();
            closeDrawer();
        });

        t(document).on("click", ".advaita-mob-sub-toggle", function(e){
            e.preventDefault();
            e.stopPropagation();
            var parentLi = t(this).closest(".advaita-mob-item");
            var subMenu = parentLi.children(".advaita-mob-sub-menu");
            
            parentLi.toggleClass("open");
            subMenu.slideToggle(250);
        });

        t(document).on("keydown", function(e){
            if (e.key === "Escape") {
                closeDrawer();
            }
        });
    }

    initMobileDrawer();
});